<template>
  <div class="login-container">
    <div class="login-form">
      <span class="title">AVE后台管理系统</span>
      <div v-if="errorText" class="error">{{ errorText }}</div>
      <div style="margin: 16px">
        <van-button round size="small" block type="primary" :loading="loading" @click="login">使用 Lark 登录</van-button>
      </div>
    </div>
  </div>
</template>

<script>
import { larkLogin } from '@/utils/sso'
import store from '@/store'

const ERROR_TEXT = {
  no_role: '未分配后台角色，请联系管理员',
  disabled: '账号已禁用',
  lark_access_denied: '不在应用访问范围，请联系管理员'
}

export default {
  name: 'Login',
  beforeRouteEnter(to, from, next) {
    if (store.state.authToken) {
      next('/')
    } else {
      next()
    }
  },
  data() {
    return {
      loading: false
    }
  },
  computed: {
    errorText() {
      const code = this.$route.query.error
      if (!code) return ''
      return ERROR_TEXT[code] || '登录失败，请重试'
    }
  },
  methods: {
    login() {
      this.loading = true
      const redirect = this.$route.query.redirect ? decodeURIComponent(this.$route.query.redirect) : '/'
      larkLogin(redirect)
    }
  }
}
</script>

